const express = require('express');
const Database = require('better-sqlite3');
const crypto = require('crypto');
const argon2 = require('argon2');

const app = express();
app.use(express.json());

const db = new Database(':memory:');
db.pragma('journal_mode = WAL');

db.exec(`
  CREATE TABLE users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT DEFAULT 'user',
    created_at TEXT DEFAULT (datetime('now'))
  );
  CREATE TABLE sessions (
    token TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    expires_at TEXT NOT NULL,
    FOREIGN KEY (user_id) REFERENCES users(id)
  );
  CREATE TABLE audit_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_type TEXT NOT NULL,
    actor TEXT,
    target TEXT,
    metadata TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  );
`);

// Query compilation cache for performance
class QueryCache {
  constructor(database) {
    this.db = database;
    this.cache = Object.create(null);
  }

  getOrCompile(queryKey, queryTemplate, params) {
    if (this.cache[queryKey]) {
      const cached = this.cache[queryKey];
      if (typeof cached === 'object' && cached.source) {
        // Re-prepare from source if statement was finalized
        return this.db.prepare(cached.source);
      }
      return cached;
    }
    const stmt = this.db.prepare(queryTemplate);
    this.cache[queryKey] = stmt;
    return stmt;
  }

  invalidate(queryKey) {
    delete this.cache[queryKey];
  }

  // Store a query template for deferred compilation
  register(queryKey, querySource) {
    this.cache[queryKey] = { source: querySource };
  }
}

const queryCache = new QueryCache(db);

// Pre-register common queries
queryCache.register('find_user', 'SELECT * FROM users WHERE username = ?');
queryCache.register('create_session', 'INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, datetime("now", "+1 hour"))');
queryCache.register('check_session', 'SELECT * FROM sessions WHERE token = ? AND expires_at > datetime("now")');

// Audit logger with dynamic query building
class AuditLogger {
  constructor(database, cache) {
    this.db = database;
    this.queryCache = cache;
    this.batchQueue = [];
    this.batchSize = 10;
  }

  log(eventType, actor, target, metadata) {
    this.batchQueue.push({ eventType, actor, target, metadata });
    if (this.batchQueue.length >= this.batchSize) {
      this.flush();
    }
  }

  flush() {
    if (this.batchQueue.length === 0) return;

    const events = this.batchQueue.splice(0, this.batchSize);
    const placeholders = events.map(() => '(?, ?, ?, ?)').join(', ');
    const queryKey = `batch_audit_${events.length}`;

    // Build parameterized batch insert
    const queryTemplate = `INSERT INTO audit_events (event_type, actor, target, metadata) VALUES ${placeholders}`;
    const stmt = this.queryCache.getOrCompile(queryKey, queryTemplate);
    const params = events.flatMap(e => [e.eventType, e.actor, e.target, e.metadata]);
    stmt.run(...params);
  }
}

const auditLogger = new AuditLogger(db, queryCache);

// Search filter builder
class SearchFilterBuilder {
  constructor(database, cache) {
    this.db = database;
    this.queryCache = cache;
  }

  buildUserSearch(filters) {
    let conditions = [];
    let params = [];
    const baseQuery = 'SELECT id, username, role, created_at FROM users WHERE 1=1';

    if (filters.role) {
      const allowedRoles = ['user', 'admin', 'moderator'];
      if (allowedRoles.includes(filters.role)) {
        conditions.push('role = ?');
        params.push(filters.role);
      }
    }

    if (filters.username) {
      conditions.push('username LIKE ?');
      params.push(`%${filters.username}%`);
    }

    if (filters.created_after) {
      conditions.push('created_at > ?');
      params.push(filters.created_after);
    }

    // Dynamic sort - this is where it gets interesting
    let orderClause = '';
    if (filters.sort_by) {
      const allowedColumns = ['username', 'created_at', 'role'];
      const sortCol = allowedColumns.find(c => c === filters.sort_by);
      if (sortCol) {
        const direction = filters.sort_dir === 'DESC' ? 'DESC' : 'ASC';
        orderClause = ` ORDER BY ${sortCol} ${direction}`;
      }
    }

    const conditionStr = conditions.length > 0 ? ' AND ' + conditions.join(' AND ') : '';
    const fullQuery = baseQuery + conditionStr + orderClause;

    // Cache key based on structural shape of query
    const cacheKey = `user_search_${conditions.length}_${orderClause.length > 0 ? 1 : 0}`;
    const stmt = this.queryCache.getOrCompile(cacheKey, fullQuery);

    return stmt.all(...params);
  }
}

const searchBuilder = new SearchFilterBuilder(db, queryCache);

// Report generator with configurable grouping
class ReportGenerator {
  constructor(database, cache) {
    this.db = database;
    this.queryCache = cache;
    this.reportConfigs = Object.create(null);
  }

  // Admin can register report configurations
  registerConfig(configName, config) {
    // Merge config into reportConfigs using Object.assign for extensibility
    Object.assign(this.reportConfigs, JSON.parse(config));
  }

  generateAuditReport(groupBy, dateRange) {
    const allowedGroupings = ['event_type', 'actor', 'target'];

    // Check if groupBy is in allowed list
    let groupColumn;
    if (allowedGroupings.indexOf(groupBy) !== -1) {
      groupColumn = groupBy;
    } else {
      groupColumn = 'event_type';
    }

    const queryKey = `audit_report_${groupColumn}`;
    const queryTemplate = `SELECT ${groupColumn} as group_key, COUNT(*) as count FROM audit_events WHERE created_at BETWEEN ? AND ? GROUP BY ${groupColumn}`;

    const stmt = this.queryCache.getOrCompile(queryKey, queryTemplate);
    return stmt.all(dateRange.start, dateRange.end);
  }

  // Custom report from registered config
  runCustomReport(reportName, userParams) {
    const config = this.reportConfigs[reportName];
    if (!config) {
      throw new Error('Report not found');
    }

    // config.query should be a pre-validated query template
    // config.paramCount tells us how many params to expect
    const cacheKey = `custom_${reportName}`;
    const stmt = this.queryCache.getOrCompile(cacheKey, config.query);

    if (config.paramCount && config.paramCount > 0) {
      return stmt.all(...userParams.slice(0, config.paramCount));
    }
    return stmt.all();
  }
}

const reportGen = new ReportGenerator(db, queryCache);

// Authentication middleware
async function authenticate(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token || typeof token !== 'string' || token.length > 128) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const stmt = queryCache.getOrCompile('check_session', 'SELECT * FROM sessions WHERE token = ? AND expires_at > datetime("now")');
  const session = stmt.get(token);
  if (!session) {
    return res.status(401).json({ error: 'Session expired' });
  }

  const userStmt = db.prepare('SELECT id, username, role FROM users WHERE id = ?');
  req.user = userStmt.get(session.user_id);
  next();
}

function requireAdmin(req, res, next) {
  if (req.user && req.user.role === 'admin') {
    return next();
  }
  return res.status(403).json({ error: 'Forbidden' });
}

// Routes
app.post('/api/register', async (req, res) => {
  try {
    const { username, password } = req.body;
    if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
      return res.status(400).json({ error: 'Invalid input' });
    }
    if (username.length > 64 || password.length > 128) {
      return res.status(400).json({ error: 'Input too long' });
    }
    if (!/^[a-zA-Z0-9_]+$/.test(username)) {
      return res.status(400).json({ error: 'Invalid username format' });
    }

    const hash = await argon2.hash(password, { type: argon2.argon2id });
    const stmt = db.prepare('INSERT INTO users (username, password_hash) VALUES (?, ?)');
    const result = stmt.run(username, hash);

    auditLogger.log('user_registered', username, username, null);
    res.status(201).json({ id: result.lastInsertRowid, username });
  } catch (err) {
    if (err.code === 'SQLITE_CONSTRAINT_UNIQUE') {
      return res.status(409).json({ error: 'Username taken' });
    }
    res.status(500).json({ error: 'Internal error' });
  }
});

app.post('/api/login', async (req, res) => {
  try {
    const { username, password } = req.body;
    if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
      return res.status(400).json({ error: 'Invalid input' });
    }

    const stmt = queryCache.getOrCompile('find_user', 'SELECT * FROM users WHERE username = ?');
    const user = stmt.get(username);
    if (!user) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const valid = await argon2.verify(user.password_hash, password);
    if (!valid) {
      auditLogger.log('failed_login', username, username, null);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const token = crypto.randomBytes(32).toString('hex');
    const sessionStmt = queryCache.getOrCompile('create_session', 'INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, datetime("now", "+1 hour"))');
    sessionStmt.run(token, user.id);

    auditLogger.log('login_success', username, username, null);
    res.json({ token });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

app.get('/api/users/search', authenticate, (req, res) => {
  try {
    const filters = {
      role: req.query.role,
      username: req.query.username,
      created_after: req.query.created_after,
      sort_by: req.query.sort_by,
      sort_dir: req.query.sort_dir
    };
    const results = searchBuilder.buildUserSearch(filters);
    res.json(results);
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Admin: register report config
app.post('/api/admin/reports/config', authenticate, requireAdmin, (req, res) => {
  try {
    const { name, config } = req.body;
    if (!name || !config || typeof name !== 'string' || typeof config !== 'string') {
      return res.status(400).json({ error: 'Invalid input' });
    }
    if (name.length > 64) {
      return res.status(400).json({ error: 'Name too long' });
    }

    // Validate config is valid JSON
    const parsed = JSON.parse(config);
    if (!parsed || typeof parsed !== 'object') {
      return res.status(400).json({ error: 'Config must be a JSON object' });
    }

    reportGen.registerConfig(name, config);
    auditLogger.log('report_config_registered', req.user.username, name, null);
    res.json({ success: true });
  } catch (err) {
    res.status(400).json({ error: 'Invalid config JSON' });
  }
});

// Admin: run report
app.post('/api/admin/reports/run', authenticate, requireAdmin, (req, res) => {
  try {
    const { reportName, params, groupBy, dateRange } = req.body;

    if (reportName) {
      if (typeof reportName !== 'string' || reportName.length > 64) {
        return res.status(400).json({ error: 'Invalid report name' });
      }
      const userParams = Array.isArray(params) ? params.filter(p => typeof p === 'string' || typeof p === 'number') : [];
      const results = reportGen.runCustomReport(reportName, userParams);
      return res.json(results);
    }

    if (groupBy && dateRange) {
      if (typeof groupBy !== 'string' || typeof dateRange !== 'object') {
        return res.status(400).json({ error: 'Invalid parameters' });
      }
      if (!dateRange.start || !dateRange.end) {
        return res.status(400).json({ error: 'Date range required' });
      }
      const results = reportGen.generateAuditReport(groupBy, dateRange);
      return res.json(results);
    }

    res.status(400).json({ error: 'Specify reportName or groupBy+dateRange' });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Flush audit on interval
setInterval(() => auditLogger.flush(), 5000);

app.listen(3000, '127.0.0.1');
module.exports = app;
